<?php
declare(strict_types=1);
header('Content-Type: text/html; charset=utf-8');
header('X-Content-Type-Options: nosniff');
function esc(string $s): string {return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function api_link(string $label,array $p,string $note=''): void {
    $url='api.php?'.http_build_query($p,'','&',PHP_QUERY_RFC3986);
    echo '<a class="example" href="'.esc($url).'" target="_blank" rel="noopener noreferrer"><span class="example-top"><strong>'.esc($label).'</strong><span aria-hidden="true">↗</span></span><code>'.esc(rawurldecode($url)).'</code>';
    if($note!=='')echo '<small>'.esc($note).'</small>';
    echo '</a>';
}
$sid='7689863296106646590';$vid='7689903116275174462';
$genres=['short_play'=>'真人剧','comic_series'=>'漫剧','ai_series'=>'AI 剧'];
?><!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Hongguo PHP · 接口文档</title>
<style>
